const root=document.querySelector('#admin'),status=document.querySelector('#status');
const el=(tag,text,attrs={})=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;for(const [k,v] of Object.entries(attrs))n.setAttribute(k,v);return n};
let session={};
async function api(path,body){const response=await fetch('/api'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json','X-CSRF-Token':session.csrf||'','Idempotency-Key':crypto.randomUUID()}:undefined,body:body?JSON.stringify(body):undefined});const data=await response.json();if(!response.ok)throw Error(data.error);return data}
const labels={BAD_CREDENTIALS:'账号或密码错误。',MFA_REQUIRED:'请输入动态验证码。',MFA_INVALID_OR_REPLAYED:'验证码无效或已使用，请使用下一枚验证码。',RATE_LIMITED:'尝试过于频繁，请稍后再试。',VERSION_CONFLICT:'内容已由他人修改，请重新加载。',FORBIDDEN:'此账号没有管理权限。',MFA_KEY_NOT_CONFIGURED:'服务器尚未配置验证器加密密钥。'};
function report(error){status.textContent=labels[error.message]||'操作未完成：'+error.message;status.className='error'}
function field(form,label,name,{type='text',value='',required=true,max=160}={}){const container=el('label',label),input=el(type==='textarea'?'textarea':'input',undefined,{name,maxlength:String(max)});if(type!=='textarea')input.type=type;input.value=value;input.required=required;container.append(input);form.append(container);return input}
function formSubmit(form,fn){form.addEventListener('submit',async event=>{event.preventDefault();if(!form.reportValidity())return;const button=form.querySelector('button[type="submit"]');if(button)button.disabled=true;status.textContent='';try{await fn(Object.fromEntries(new FormData(form)))}catch(error){report(error)}finally{if(button)button.disabled=false}})}
function login(){root.replaceChildren();const panel=el('section',undefined,{class:'panel'}),form=el('form',undefined,{class:'form',id:'loginForm'});panel.append(el('h2','管理员登录'));field(form,'账号','username');field(form,'密码','password',{type:'password',max:128});field(form,'动态验证码（已绑定时填写）','otp',{required:false,max:6});form.append(el('button','登录',{type:'submit',class:'primary'}));formSubmit(form,async body=>{session=await api('/login',body);await render()});panel.append(form);root.append(panel)}
function enroll(){const panel=el('section',undefined,{class:'panel'}),form=el('form',undefined,{class:'form',id:'enrollForm'});panel.append(el('h2','先绑定管理员动态验证码'),el('p','绑定前不能管理商品或查看咨询。请先配置服务器MFA密钥文件。'));field(form,'确认当前密码','password',{type:'password',max:128});form.append(el('button','开始绑定',{type:'submit',class:'primary'}));formSubmit(form,async body=>{const setup=await api('/admin/mfa/begin',body);panel.replaceChildren(el('h2','将密钥手动添加到验证器'),el('p','此密钥仅供本人绑定，请勿发送给他人。'),el('code',setup.secret,{class:'secret'}));const confirm=el('form',undefined,{class:'form',id:'confirmMfaForm'});field(confirm,'六位验证码','otp',{max:6});confirm.append(el('button','确认绑定',{type:'submit',class:'primary'}));formSubmit(confirm,async data=>{await api('/admin/mfa/confirm',data);await render()});panel.append(confirm)});panel.append(form);root.append(panel)}
function productForm(product){const dialog=el('dialog'),close=el('button','关闭',{type:'button',class:'close'});close.onclick=()=>dialog.close();dialog.append(close,el('h2',product?'编辑商品':'新增真实商品'));const form=el('form',undefined,{class:'form',id:'productForm'});for(let i=0;i<3;i++){field(form,['中文标题','English title','日本語タイトル'][i],'name'+i,{value:product?.names[i]||''});field(form,['中文说明','English description','日本語説明'][i],'description'+i,{type:'textarea',value:product?.descriptions[i]||'',max:4000})}field(form,'已获使用许可的图片HTTPS地址（选填）','image_url',{type:'url',value:product?.image_url||'',required:false,max:2000});const label=el('label',undefined,{class:'check'}),published=el('input',undefined,{type:'checkbox',name:'published'});published.checked=product?.status==='published';label.append(published,el('span','公开展示（必须是真实、可核实的商品信息）'));form.append(label,el('button','保存',{type:'submit',class:'primary'}));formSubmit(form,async data=>{await api('/catalog/products/save',{id:product?.id,version:product?.version,names:[data.name0,data.name1,data.name2],descriptions:[data.description0,data.description1,data.description2],image_url:data.image_url,published:published.checked});dialog.close();await render()});dialog.append(form);document.body.append(dialog);dialog.addEventListener('close',()=>dialog.remove());dialog.showModal()}
async function render(){session=await api('/session');root.replaceChildren();status.textContent='';if(!session.user)return login();if(session.user.role!=='admin'){root.append(el('p','此账号没有管理权限。'));return}const logout=el('button','退出',{type:'button'});logout.onclick=async()=>{try{await api('/logout',{});await render()}catch(error){report(error)}};root.append(logout);const security=await api('/admin/security');if(!security.enabled)return enroll();const data=await api('/catalog/admin');const productsPanel=el('section',undefined,{class:'panel'}),add=el('button','新增商品',{type:'button',class:'primary'});add.onclick=()=>productForm();productsPanel.append(el('h2','商品展示'),add);if(!data.products.length)productsPanel.append(el('p','尚无商品。不会自动将测试商品发布为正式商品。'));for(const product of data.products){const row=el('div',undefined,{class:'row'}),edit=el('button','编辑',{type:'button'});edit.onclick=()=>productForm(product);row.append(el('p',product.names[0]+' · '+(product.status==='published'?'已公开':'草稿')+' · v'+product.version),edit);productsPanel.append(row)}root.append(productsPanel);const inquiriesPanel=el('section',undefined,{class:'panel'});inquiriesPanel.append(el('h2','咨询收件箱（最近100条）'),el('p','信息仅保存于本站，没有发送自动邮件。请按隐私说明处理并通过已授权渠道回复。'));if(!data.inquiries.length)inquiriesPanel.append(el('p','暂无咨询。'));for(const inquiry of data.inquiries){const article=el('article',undefined,{class:'card inquiry'});article.append(el('h3',inquiry.id),el('p','状态：'+inquiry.status+' · '+new Date(inquiry.created).toLocaleString()),el('p','联系：'+inquiry.email+' · '+inquiry.name),el('p','商品：'+(inquiry.product_snapshot?.names[0]||'通用咨询')),el('p',inquiry.message));const button=el('button',inquiry.status==='open'?'标记已处理':'重新打开',{type:'button'});button.onclick=async()=>{try{await api('/catalog/inquiries/update',{id:inquiry.id,status:inquiry.status==='open'?'closed':'open'});await render()}catch(error){report(error)}};article.append(button);inquiriesPanel.append(article)}root.append(inquiriesPanel)}
try{await render()}catch(error){report(error)}
